#include <iostream>
#include <vector>
#include <set>
#include <numeric>

using namespace std;

/**
 * Problem: 2009-24 - Unique lines
 * 
 * 解題思路：
 * 1. 每兩個點 (x1, y1) 和 (x2, y2) 決定一條直線。
 * 2. 直線方程可表示為 ax + by + c = 0。
 * 3. 係數 a = y1 - y2, b = x2 - x1, c = x1*y2 - x2*y1。
 * 4. 為了使表示唯一，將 (a, b, c) 除以其最大公因數 gcd(a, b, c)，
 *    並規定 a > 0，若 a = 0 則 b > 0。
 * 5. 使用 std::set 儲存唯一的 (a, b, c) 組並統計個數。
 */

struct Line {
    int a, b, c;
    bool operator<(const Line& other) const {
        if (a != other.a) return a < other.a;
        if (b != other.b) return b < other.b;
        return c < other.c;
    }
};

int gcd(int a, int b) { return b == 0 ? a : gcd(b, a % b); }

int main() {
    int T;
    cin >> T;
    while (T--) {
        int N;
        cin >> n;
        vector<pair<int, int>> p(N);
        for (int i = 0; i < N; ++i) cin >> p[i].first >> p[i].second;

        set<Line> lines;
        for (int i = 0; i < N; ++i) {
            for (int j = i + 1; j < N; ++j) {
                int a = p[i].second - p[j].second;
                int b = p[j].first - p[i].first;
                int c = p[i].first * p[j].second - p[j].first * p[i].second;
                int g = gcd(abs(a), gcd(abs(b), abs(c)));
                a /= g; b /= g; c /= g;
                if (a < 0 || (a == 0 && b < 0)) { a = -a; b = -b; c = -c; }
                lines.insert({a, b, c});
            }
        }
        cout << lines.size() << endl;
    }
    return 0;
}
